    "caption": "<b>УЧИМ ИВРИТ • BIT / PAYBOX 📲: 4 готовые фразы на иврите</b>\n\n<i>4 фразы в складчину: переведи на номер, запрос платежа, готово</i>\n\n🔊 <b>Слушайте произношение на карточках:</b>\n\n<b>1️⃣ ПЕРЕВЕДИ НА BIT</b>\n<code>אַתָּה יָכוֹל לְהַעֲבִיר לִי בְּבִיט לְפִי מִסְפַּר הַטֶּלֶפוֹן?</code>\n<i>(Ата́ яхо́ль лэhаави́р ли бэ-Бит лэфи́ миспа́р hа-тэ́лефон?)</i>\n\n<b>2️⃣ Я УЖЕ ОТПРАВИЛ</b>\n<code>הַרְגַּע הֶעֱבַרְתִּי לְךָ חֲמִשִּׁים שֶׁקֶל, תִּבְדּוֹק שֶׁהִגִּיעַ.</code>\n<i>(hа́рга hээва́рти лэха́ хамиши́м шэ́кэль, тивдо́к шэ-hиги́а)</i>\n\n<b>3️⃣ ЗАПРОС ОПЛАТЫ</b>\n<code>תִּשְׁלַח לִי בַּקָּשַׁת תַּשְׁלוּם בָּאַפְּלִיקַצְיָה וַאֲנִי אֲאַשֵּׁר.</code>\n<i>(Тишла́х ли бакаша́т ташлу́м ба-аплика́ция ва-ани́ а’ашэ́р)</i>\n\n<b>4️⃣ ДЕНЬГИ ПРИШЛИ</b>\n<code>הַכֹּל בְּסֵדֶר, הַהַעֲבָרָה הִתְקַבְּלָה בְּהַצְלָחָה, תּוֹדָה!</code>\n<i>(hа-коль бэ-сэ́дэр, hа-hаавара́ hиткабла́ бэ-hацлаха́, тода́!)</i>\n\n💡 <b>Хотите говорить на иврите свободно и без страха звонить?</b>\nОтрабатывайте живые диалоги в интерактивном тренажёре «Ульпан Алеф».\n\n👉 <a href=\"https://ulpana-hebrew.vercel.app/#lesson-20?promo=TG&utm_source=telegram&utm_medium=channel&utm_campaign=sc-19-bit-paybox-payment\">Начать практику (30 дней бесплатно с промокодом TG)</a>\n",
