    "caption": "УЧИМ ИВРИТ • ТАКСИ 🚖: 4 фразы на иврите\n\n4 фразы в поездке: включить счётчик, остановите на углу, сдача\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ ВКЛЮЧИТЕ СЧЁТЧИК\nתַּפְעִיל אֶת הַמּוֹנֶה בְּבַקָּשָׁה, אֲנִי לֹא נוֹסֵעַ בִּמְחִיר קָבוּעַ.\n(Таф’и́ль эт hа-монэ́ бэ-вакаша́, ани́ ло носэ́а би-мхи́р каву́а)\n\n2️⃣ ОСТАНОВИТЕ НА УГЛУ\nתַּעֲצוֹר לִי פֹּה בְּפִנַּת הָרְחוֹב, אֲנִי אֵרֵד כָּאן.\n(Таацо́р ли по бэ-пина́т hа-рэхо́в, ани́ эрэ́д кан)\n\n3️⃣ ОПЛАТА В ПРИЛОЖЕНИИ\nהַנְּסִיעָה מְשֻׁלֶּמֶת בָּאַשְׁרַאי דֶּרֶךְ הָאַפְּלִיקַצְיָה, נָכוֹן?\n(hа-нси’а́ мэшулэ́мэт ба-ашра́й дэ́рэх hа-аплика́ция, нахо́н?)\n\n4️⃣ ОСТАВЬТЕ СДАЧУ\nתּוֹדָה עַל הַנְּסִיעָה הַמְּהִירָה, תַּשְׁאִיר אֶת הָעֹדֶף אֶצְלְךָ.\n(Тода́ аль hа-нси’а́ hа-мэhира́, таш’и́р эт hа-о́дэф эцльха́)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
