    "caption": "УЧИМ ИВРИТ • РАБОТА 💼: 4 фразы на иврите\n\n4 уверенные фразы: опыт работы, резюме, готов приступить\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ ОПЫТ РАБОТЫ\nיֵשׁ לִי חָמֵשׁ שְׁנוֹת נִסָּיוֹן מִקְצוֹעִי בַּתְּחוּם הַזֶּה.\n(Йеш ли хамэ́ш шнот нисайо́н микцо’и́ ба-тхум hа-зэ)\n\n2️⃣ ОТПРАВИЛ РЕЗЮМЕ\nשָׁלַחְתִּי קוֹרוֹת חַיִּים מְעֻדְכָּנִים וְהַמְלָצוֹת בַּמֵּיְל.\n(Шала́хти коро́т хаи́м мэуддани́м вэ-hамлацо́т ба-мэйл)\n\n3️⃣ ГОТОВ ПРИСТУПИТЬ\nאֲנִי יָכוֹל לְהַתְחִיל לַעֲבוֹד בְּמִשְׂרָה מְלֵאָה מֵשָׁבוּעַ הַבָּא.\n(Ани́ яхо́ль лэhатхи́ль лааво́д бэ-мисра́ млэ’а́ мэ-шаву́а hа-ба)\n\n4️⃣ УРОВЕНЬ ИВРИТА\nהָעִבְרִית שֶׁלִּי מִשְׁתַּפֶּרֶת כָּל יוֹם, אֲנִי מֵבִין וּמְדַבֵּר חָפְשִׁי.\n(hа-иври́т шели́ миштапэ́рэт коль йом, ани́ мэви́н у-мэдабэ́р хофши́)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
