    "caption": "<b>УЧИМ ИВРИТ • РАБОТА 💼: 4 готовые фразы на иврите</b>\n\n<i>4 уверенные фразы: опыт работы, резюме, готов приступить</i>\n\n🔊 <b>Слушайте произношение на карточках:</b>\n\n<b>1️⃣ ОПЫТ РАБОТЫ</b>\n<code>יֵשׁ לִי חָמֵשׁ שְׁנוֹת נִסָּיוֹן מִקְצוֹעִי בַּתְּחוּם הַזֶּה.</code>\n<i>(Йеш ли хамэ́ш шнот нисайо́н микцо’и́ ба-тхум hа-зэ)</i>\n\n<b>2️⃣ ОТПРАВИЛ РЕЗЮМЕ</b>\n<code>שָׁלַחְתִּי קוֹרוֹת חַיִּים מְעֻדְכָּנִים וְהַמְלָצוֹת בַּמֵּיְל.</code>\n<i>(Шала́хти коро́т хаи́м мэуддани́м вэ-hамлацо́т ба-мэйл)</i>\n\n<b>3️⃣ ГОТОВ ПРИСТУПИТЬ</b>\n<code>אֲנִי יָכוֹל לְהַתְחִיל לַעֲבוֹד בְּמִשְׂרָה מְלֵאָה מֵשָׁבוּעַ הַבָּא.</code>\n<i>(Ани́ яхо́ль лэhатхи́ль лааво́д бэ-мисра́ млэ’а́ мэ-шаву́а hа-ба)</i>\n\n<b>4️⃣ УРОВЕНЬ ИВРИТА</b>\n<code>הָעִבְרִית שֶׁלִּי מִשְׁתַּפֶּרֶת כָּל יוֹם, אֲנִי מֵבִין וּמְדַבֵּר חָפְשִׁי.</code>\n<i>(hа-иври́т шели́ миштапэ́рэт коль йом, ани́ мэви́н у-мэдабэ́р хофши́)</i>\n\n💡 <b>Хотите говорить на иврите свободно и без страха звонить?</b>\nОтрабатывайте живые диалоги в интерактивном тренажёре «Ульпан Алеф».\n\n👉 <a href=\"https://ulpana-hebrew.vercel.app/#lesson-17?promo=TG&utm_source=telegram&utm_medium=channel&utm_campaign=sc-16-job-interview\">Начать практику (30 дней бесплатно с промокодом TG)</a>\n",
