    "caption": "УЧИМ ИВРИТ • МАГАЗИН 👗: 4 фразы на иврите\n\n4 фразы в магазине: примерочная, размер побольше, обмен\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ ГДЕ ПРИМЕРОЧНАЯ\nסְלִיחָה, אֵיפֹה נִמְצָאִים פֹּה תָּאֵי הַמְּדִידָה?\n(Слиха́, э́йфо нимцаи́м по та’э́й hа-мэдида́?)\n\n2️⃣ РАЗМЕР ПОБОЛЬШЕ\nהַחֻלְצָה הַזֹּאת קְטַנָּה עָלַי, יֵשׁ מִדָּה אַחַת יוֹתֵר גְּדוֹלָה?\n(hа-хульца́ hа-зот ктана́ ала́й, йеш мида́ аха́т йотэ́р гдола́?)\n\n3️⃣ ДРУГОЙ ЦВЕТ\nיֵשׁ אֶת הַמִּכְנָסַיִם הָאֵלֶּה בְּצֶבַע שָׁחֹר אוֹ כָּחֹל בַּמַּחְסָן?\n(Йеш эт hа-михнаса́им hа-э́ле бэ-цэ́ва шахо́р о кахо́ль ба-махса́н?)\n\n4️⃣ ОБМЕНЯТЬ ТОВАР\nכַּמָּה יָמִים יֵשׁ לִי כְּדֵי לְהַחְלִיף עִם הַקַּבָּלָה?\n(Ка́ма ями́м йеш ли кдэй лэhахли́ф им hа-кабала́?)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
