    "caption": "УЧИМ ИВРИТ • АПТЕКА 💊: 4 фразы на иврите\n\n4 фразы при покупке: без рецепта, от аллергии, жаропонижающее\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ ОБЕЗБОЛИВАЮЩЕЕ\nמָה יֵשׁ לָכֶם חָזָק נֶגֶד כְּאֵב רֹאשׁ בְּלִי מִרְשָׁם?\n(Ма йеш лахэ́м хаза́к нэ́гэд к’эв рош бли мирша́м?)\n\n2️⃣ СПРЕЙ ДЛЯ НОСА\nאֲנִי צְרִיכָה תַּרְסִיס לָאַף נֶגֶד נַזֶּלֶת קָשָׁה.\n(Ани́ цриха́ тарси́с ла-аф нэ́гэд назэ́лет каша́)\n\n3️⃣ КАК ПРИНИМАТЬ\nכַּמָּה פְּעָמִים בְּיוֹם לוֹקְחִים אֶת הַכַּדּוּרִים: לִפְנֵי אוֹ אַחֲרֵי הָאֹכֶל?\n(Ка́ма паами́м бэ-йом локхи́м эт hа-кадури́м: лифнэ́й о ахарэ́й hа-о́хель?)\n\n4️⃣ ЛЕКАРСТВО ДЛЯ ДЕТЕЙ\nיֵשׁ לָכֶם סִירוֹפּ אֲקָמוֹל לִילָדִים לְהוֹרָדַת חֹם?\n(Йеш лахэ́м си́роп Акамо́ль ли-йлади́м лэ-hорада́т хом?)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
