    "caption": "УЧИМ ИВРИТ • АВТОБУС 🚌: 4 фразы на иврите\n\n4 фразы в транспорте: открыть заднюю дверь, пересадка, остановка\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ ОТКРОЙТЕ СЗАДИ\nנַהָג, תִּפְתַּח מֵאָחוֹר בְּבַקָּשָׁה, אֲנִי יוֹרֵד!\n(Наhа́г, тифта́х мэ-ахо́р бэ-вакаша́, ани́ йорэ́д!)\n\n2️⃣ ОСТАНОВКА У БОЛЬНИЦЫ\nהָאוֹטוֹבּוּס הַזֶּה מַגִּיעַ לְבֵית חוֹלִים אִיכִילוֹב?\n(hа-о́тобус hа-зэ маги́а лэ-вэйт холи́м Ихи́лов?)\n\n3️⃣ ВАЛИДАЦИЯ НЕ СРАБОТАЛА\nהַמַּכְשִׁיר לֹא סוֹרֵק אֶת הָאַפְּלִיקַצְיָה, אֶפְשָׁר לִבְדּוֹק?\n(hа-махши́р ло сорэ́к эт hа-аплика́ция, эфша́р ливдо́к?)\n\n4️⃣ СЛЕДУЮЩАЯ ОСТАНОВКА\nאַתָּה יָכוֹל לְהַגִּיד לִי מָתַי תִּהְיֶה רְחוֹב דִּיזֶנְגּוֹף?\n(Ата́ яхо́ль лэhаги́д ли мата́й тиhйе́ рэхо́в Дизенго́ф?)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
