    "caption": "УЧИМ ИВРИТ • КОФЕЙНЯ ☕: 4 фразы на иврите\n\n4 фразы для идеального заказа: афух, овсяное молоко, с собой\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ МАЛЕНЬКИЙ КАПУЧИНО\nהָפוּךְ קָטָן עַל חֲלַב שִׁבּוֹלֶת שׁוּעָל, בְּלִי סֻכָּר, לָקַחַת.\n(hафу́х ката́н аль хала́в шибо́лет шу’а́ль, бли сука́р, ла-ка́хат)\n\n2️⃣ СТАКАН ВОДЫ\nאֶפְשָׁר כּוֹס מַיִם קָרִים עִם קֶרַח בְּצַד, בְּבַקָּשָׁה?\n(Эфша́р кос ма́им кари́м им кэ́рах бэ-цад, бэ-вакаша́?)\n\n3️⃣ СКОЛЬКО СТОИТ ВЫПЕЧКА\nכַּמָּה עוֹלָה הַמַּאֲפָה שְׁקֵדִים הַזֹּאת?\n(Ка́ма ола́ hа-маафа́ шкеди́м hа-зот?)\n\n4️⃣ РАЗОГРЕТЬ ЕДУ\nאֶפְשָׁר לְחַמֵּם לִי אֶת הַקְרוּאָסוֹן קְצָת?\n(Эфша́р лэхамэ́м ли эт hа-круасо́н кцат?)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
