    "caption": "<b>УЧИМ ИВРИТ • КОФЕЙНЯ ☕: 4 готовые фразы на иврите</b>\n\n<i>4 фразы для идеального заказа: афух, овсяное молоко, с собой</i>\n\n🔊 <b>Слушайте произношение на карточках:</b>\n\n<b>1️⃣ МАЛЕНЬКИЙ КАПУЧИНО</b>\n<code>הָפוּךְ קָטָן עַל חֲלַב שִׁבּוֹלֶת שׁוּעָל, בְּלִי סֻכָּר, לָקַחַת.</code>\n<i>(hафу́х ката́н аль хала́в шибо́лет шу’а́ль, бли сука́р, ла-ка́хат)</i>\n\n<b>2️⃣ СТАКАН ВОДЫ</b>\n<code>אֶפְשָׁר כּוֹס מַיִם קָרִים עִם קֶרַח בְּצַד, בְּבַקָּשָׁה?</code>\n<i>(Эфша́р кос ма́им кари́м им кэ́рах бэ-цад, бэ-вакаша́?)</i>\n\n<b>3️⃣ СКОЛЬКО СТОИТ ВЫПЕЧКА</b>\n<code>כַּמָּה עוֹלָה הַמַּאֲפָה שְׁקֵדִים הַזֹּאת?</code>\n<i>(Ка́ма ола́ hа-маафа́ шкеди́м hа-зот?)</i>\n\n<b>4️⃣ РАЗОГРЕТЬ ЕДУ</b>\n<code>אֶפְשָׁר לְחַמֵּם לִי אֶת הַקְרוּאָסוֹן קְצָת?</code>\n<i>(Эфша́р лэхамэ́м ли эт hа-круасо́н кцат?)</i>\n\n💡 <b>Хотите говорить на иврите свободно и без страха звонить?</b>\nОтрабатывайте живые диалоги в интерактивном тренажёре «Ульпан Алеф».\n\n👉 <a href=\"https://ulpana-hebrew.vercel.app/#lesson-2?promo=TG&utm_source=telegram&utm_medium=channel&utm_campaign=sc-05-cafe-order\">Начать практику (30 дней бесплатно с промокодом TG)</a>\n",
