    "caption": "УЧИМ ИВРИТ • КОФЕЙНЯ ☕: 4 готовые фразы на иврите\n\n4 фразы для идеального заказа: афух, овсяное молоко, с собой\n\nВключайте видео со звуком 🔊 — внутри правильное нативное произношение:\n\n1️⃣ МАЛЕНЬКИЙ КАПУЧИНО:\nהָפוּךְ קָטָן עַל חֲלַב שִׁבּוֹלֶת שׁוּעָל, בְּלִי סֻכָּר, לָקַחַת.\n(hафу́х ката́н аль хала́в шибо́лет шу’а́ль, бли сука́р, ла-ка́хат)\n\n2️⃣ СТАКАН ВОДЫ:\nאֶפְשָׁר כּוֹס מַיִם קָרִים עִם קֶרַח בְּצַד, בְּבַקָּשָׁה?\n(Эфша́р кос ма́им кари́м им кэ́рах бэ-цад, бэ-вакаша́?)\n\n3️⃣ СКОЛЬКО СТОИТ ВЫПЕЧКА:\nכַּמָּה עוֹלָה הַמַּאֲפָה שְׁקֵדִים הַזֹּאת?\n(Ка́ма ола́ hа-маафа́ шкеди́м hа-зот?)\n\n4️⃣ РАЗОГРЕТЬ ЕДУ:\nאֶפְשָׁר לְחַמֵּם לִי אֶת הַקְרוּאָסוֹן קְצָת?\n(Эфша́р лэхамэ́м ли эт hа-круасо́н кцат?)\n\nСохраняйте себе в закладки, чтобы нужные слова всегда были под рукой!\n(Ссылка на интерактивный тренажёр живых диалогов — в первом комментарии к этому видео 👇)\n",
