    "caption": "УЧИМ ИВРИТ • СУПЕРМАРКЕТ 🛒: 4 фразы на иврите\n\n4 бытовые фразы: пакеты, скидка клуба, чек, самообслуживание\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ ПАКЕТЫ НА КАССЕ\nאֲנִי צָרִיךְ שְׁתֵּי שַׂקִּיּוֹת גְּדוֹלוֹת, בְּבַקָּשָׁה.\n(Ани́ цари́х штэй сакиё́т гдоло́т, бэ-вакаша́)\n\n2️⃣ КАРТА КЛУБА\nאֵין לִי כַּרְטִיס מוֹעֲדוֹן, אֶפְשָׁר לְחַשֵּׁב רָגִיל?\n(Эйн ли карти́с моадо́н, эфша́р лэ-хашэ́в раги́ль?)\n\n3️⃣ СКИДКА ПО АКЦИИ\nהַגְּבִינָה הַזֹּאת בְּמִבְצָע עַכְשָׁו, שְׁנַיִם בִּמְחִיר אֶחָד?\n(hа-гвина́ hа-зот бэ-мивца́ ахша́в, шна́им би-мхи́р эха́д?)\n\n4️⃣ ОПЛАТА ПО БЕЗНАЛУ\nאֲנִי מְשַׁלֵּם בַּטֶּלֶפוֹן, עִם הַצְמָדָה לַמַּסוֹף.\n(Ани́ мешалэм ба-тэ́лефон, им hацмада́ ла-масо́ф)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
