    "caption": "УЧИМ ИВРИТ • ПОЛИКЛИНИКА 🩺: 4 фразы на иврите\n\n4 фразы терапевту: больничный, анализы, рецепт на лекарство\n\nЛистайте карусель 👉 внутри 4 готовые фразы с правильным ударением:\n\n1️⃣ БОЛЬНИЧНЫЙ ЛИСТ\nאֲנִי צָרִיךְ אִשּׁוּר מַחֲלָה לָעֲבוֹדָה לִשְׁלוֹשָׁה יָמִים, בְּבַקָּשָׁה.\n(Ани́ цари́х ишу́р махала́ ла-авода́ лишлоша́ ями́м, бэ-вакаша́)\n\n2️⃣ НАПРАВЛЕНИЕ НА АНАЛИЗЫ\nדּוֹקְטוֹר, אֶפְשָׁר הַפְנָיָה לִבְדִיקַת דָּם כְּלָלִית?\n(До́ктор, эфша́р hафная́ ли-вдика́т дам клали́т?)\n\n3️⃣ РЕЦЕПТ В АПТЕКУ\nשָׁלַחְתָּ אֶת הַמִּרְשָׁם יָשָׁר לַכַּרְטִיס הַמַּגְנֶטִי?\n(Шала́хта эт hа-мирша́м яша́р ла-карти́с hа-магнэ́ти?)\n\n4️⃣ БОЛЬ И СИМПТОМЫ\nיֵשׁ לִי סְחַרְחֹרֶת חֲזָקָה וְכֹאֵב לִי הַגָּרוֹן מֵאֶתְמוֹל.\n(Йеш ли схархо́рет хазака́ вэ-коэ́в ли hа-гаро́н мэ-этмо́ль)\n\n💾 Обязательно сохраняйте в закладки, чтобы нужные слова всегда были под рукой!\n\n🎁 Хотите потренироваться отвечать и говорить на иврите без ступора и переводчика?\nПереходите по ссылке в шапке профиля @ulpana_alef — там открыт интерактивный тренажёр живых диалогов и звонков.\nПромокод на 30 дней бесплатного доступа: INSTA ✨\n\n💬 Напишите «ИВРИТ» в комментариях 👇 — и мы пришлём прямую ссылку в Директ!\n\n#иврит #урокииврита #ивритдляначинающих #ивритизраиль #ульпан #ульпаналеф #репатриация #жизньвизраиле #олимхадашим #разговорныйиврит\n",
